def plasma_density(x, y):
    s = np.clip((x - 64.0) / 40.0, 0.0, 1.0)
    return 0.072 * np.sin(0.5 * math.pi * s)**2

def rise(s):
    return np.sin(0.5 * math.pi * np.clip(s / 4.0, 0.0, 1.0))**2

def dopant_density(x, y):
    sec = rise(x - 108.0) * (1.0 - rise(x - 132.0))
    return 0.0007199999999999999 * plasma_density(x, y) / 0.072 * sec * (np.abs(y - 50.26548245743669) < 14.137166941154067)

Species(
    name = "electron",
    position_initialization = "regular",
    regular_number = [2, 2],
    momentum_initialization = "cold",
    particles_per_cell = 4,
    mass = 1.0, charge = -1.0,
    number_density = plasma_density,
    boundary_conditions = [["remove", "remove"], ["remove", "remove"]],
)

